    ('WA-10',  'Wheel assembly, 10 in',     'EA',  9.85),
    ('AX-10',  'Axle, 5/8 in',              'EA',  1.95),
    ('TU-12',  'Steel tubing, 1 in',        'FT',  1.10),
    ('BS-075', 'Bar stock, 5/8 in',         'FT',  1.30),
